const rows=$('Read Financial Transactions').all().map(x=>x.json||{}).filter(x=>x.Date&&x.Event_ID&&x.Status!=='Ignored'&&x.Status!=='Duplicate');
const budgets=$('Read Category Budgets').all().map(x=>x.json||{});
const settings=Object.fromEntries($input.all().map(x=>x.json||{}).filter(x=>x.Setting).map(x=>[String(x.Setting),String(x.Value??'')]));
const enabled=x=>/^(true|yes|1|on)$/i.test(String(x||'').trim());
const email=String(settings['Report email']||'').trim();
if(!enabled(settings['Daily email enabled'])||!/^[-.\w+]+@[-.\w]+\.[a-z]{2,}$/i.test(email))return [];
const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
const datePart=k=>parts.find(x=>x.type===k)?.value||'';
const today=datePart('year')+'-'+datePart('month')+'-'+datePart('day');
const asDate=new Date(today+'T12:00:00Z'),day=asDate.getUTCDay();
const weekStart=new Date(asDate);weekStart.setUTCDate(asDate.getUTCDate()-((day+6)%7));
const ymd=x=>x.toISOString().slice(0,10),mStart=today.slice(0,7);
const amount=x=>{const n=Number(String(x.Amount_NGN||'').replace(/,/g,''));return Number.isFinite(n)?n:0;};
const total=(a,fn)=>a.filter(fn).reduce((acc,x)=>acc+amount(x),0);
const money=n=>'₦'+Number(n||0).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2});
const metrics=a=>({
 count:a.length,
 credit:total(a,x=>x.Direction==='Credit'),
 debit:total(a,x=>x.Direction==='Debit'),
 expense:total(a,x=>x.Direction==='Debit'&&x.Type==='Expense'),
 unknown:total(a,x=>x.Direction==='Debit'&&x.Type==='Unclassified Debit'),
 transfers:total(a,x=>x.Direction==='Debit'&&x.Type==='Internal Transfer'),
 possible:total(a,x=>x.Direction==='Debit'&&x.Type==='Possible Transfer')
});
const line=(label,arr)=>{const m=metrics(arr);return label+'\nCredits received: '+money(m.credit)+'\nDebits recorded: '+money(m.debit)+'\nNet account movement: '+money(m.credit-m.debit)+'\nCategorised expenses: '+money(m.expense)+'\nUnclassified debits: '+money(m.unknown)+'\nOwn-account transfers out: '+money(m.transfers)+'\nPossible transfers out: '+money(m.possible)+'\nTransactions recorded: '+m.count;};
const monthRows=rows.filter(x=>String(x.Date).startsWith(mStart)),todayRows=rows.filter(x=>String(x.Date)===today);
const warnings=[],thresholdRaw=Number(settings['Warn at percentage of budget']),threshold=Number.isFinite(thresholdRaw)&&thresholdRaw>=1&&thresholdRaw<=100?thresholdRaw:80;
const monthExpense=metrics(monthRows).expense,monthlyLimit=Number(String(settings['Overall monthly spending limit (₦)']||'').replace(/,/g,''));
if(monthlyLimit>0&&monthExpense/monthlyLimit*100>=threshold)warnings.push('Overall classified spending '+money(monthExpense)+' / '+money(monthlyLimit)+' ('+Math.round(monthExpense/monthlyLimit*100)+'%)');
for(const b of budgets){
 const category=String(b['Expense category']||'').trim();
 const budget=Number(String(b['Monthly budget (₦)']||'').replace(/,/g,''));
 if(!category||category==='Unknown'||!(budget>0))continue;
 const spent=total(monthRows,x=>x.Direction==='Debit'&&x.Type==='Expense'&&x.Category===category);
 if(spent/budget*100>=threshold)warnings.push(category+': '+money(spent)+' / '+money(budget)+' ('+Math.round(spent/budget*100)+'%)');
}
let message='FINANCIAL SAVVY WOMAN | DAILY MONEY REPORT\n'+today+'\n\n'+line('TODAY',todayRows);
const isSunday=day===0&&enabled(settings['Sunday weekly recap enabled']);
if(isSunday){
 const weekRows=rows.filter(x=>String(x.Date)>=ymd(weekStart)&&String(x.Date)<=today);
 message+='\n\n'+line('WEEKLY RECAP ('+ymd(weekStart)+' to '+today+')',weekRows);
}
if(warnings.length)message+='\n\nBUDGET WARNINGS (threshold '+threshold+'%)\n'+warnings.map(x=>'• '+x).join('\n');
else message+='\n\nBudget alerts: No configured spending threshold reached. Add budgets in Categories & Rules and Alert Settings.';
message+='\n\nIMPORTANT: Bank debits can include transfers, fees, and uncategorised movements. Only purpose-classified debits count as spending here. Missing bank alerts can make the totals incomplete.\n\nGenerated automatically from Financial Savvy Woman.';
return [{json:{sendTo:email,subject:'Financial Savvy Woman | '+(isSunday?'Daily + Weekly':'Daily')+' report | '+today+(warnings.length?' | Budget warning':''),message,day:today,warningCount:warnings.length}}];
